/* Theme loader. Generated by tools/build_themes.py from content/themes.json.
   The themes themselves are in site.css. On arithim.com every visitor gets the default theme. On any other
   host (a preview, localhost), ?theme=<name> picks a theme, the choice is remembered, and a picker appears. */
(function () {
  var DEFAULT = "arithim";
  var LABELS = {"arithim": "Arithim dark (current)", "light": "Light, slate and amber (draft)"};
  var prod = /(^|\.)arithim\.com$/.test(location.hostname);
  var name = DEFAULT;
  try {
    if (!prod) {
      var q = new URLSearchParams(location.search).get('theme');
      if (q && LABELS.hasOwnProperty(q)) localStorage.setItem('ah-theme', q);
      var saved = localStorage.getItem('ah-theme');
      if (saved && LABELS.hasOwnProperty(saved)) name = saved;
    }
  } catch (e) {}
  document.documentElement.setAttribute('data-theme', name);
  if (prod) return;
  document.addEventListener('DOMContentLoaded', function () {
    var box = document.createElement('label');
    box.style.cssText = 'position:fixed;left:12px;bottom:12px;z-index:99999;font:12px/1.2 system-ui,sans-serif;background:#111;color:#fff;padding:8px 10px;border-radius:8px;opacity:.92';
    box.textContent = 'Theme ';
    var sel = document.createElement('select');
    sel.style.cssText = 'font:inherit;margin-left:6px;background:#222;color:#fff;border:1px solid #555;border-radius:4px';
    Object.keys(LABELS).forEach(function (n) { var o = document.createElement('option'); o.value = n; o.textContent = LABELS[n]; if (n === name) o.selected = true; sel.appendChild(o); });
    sel.onchange = function () { try { localStorage.setItem('ah-theme', sel.value); } catch (e) {} location.reload(); };
    box.appendChild(sel);
    document.body.appendChild(box);
  });
})();
